(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-1101","batch":"23","category":"Categoria B","question":"Precizați măsura care se ia atunci când titularul permisului de conducere a fost declarat inapt pentru a conduce autovehicule, de către o instituție medicală autorizată:","answers":["I se retrage permisul de conducere","I se aplică sancțiunile contravenționale complementare","Va fi reexaminat de către autoritatea competentă"],"correctIndices":[0],"correct":0,"explanation":"Retragerea permisului de conducere se dispune de către poliția rutieră dacă titularul acestuia a fost declarat inapt medical sau inapt psihologic pentru a conduce autovehicule, tractoare agricole sau forestiere ori tramvaie.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1101.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1101.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1101; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1100 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/precizati-masura-care-se-ia-atunci-cand-titularul-permisului-de-conducere-a-fost-declarat-inapt-pentru-a-conduce-autovehicule-de-catre-o-ins","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1100","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1102","batch":"23","category":"Categoria B","question":"În ce situații se interzice circulația autoturismelor pe drumurile publice?","answers":["Când nu au montate faruri de ceață","Când motorul emite noxe peste limita legală","Când nu sunt echipate cu cârlig pentru remorcare"],"correctIndices":[1],"correct":1,"explanation":"Legislația rutieră nu interzice circulația autoturismelor când nu au montate faruri de ceață, acestea nu sunt obligatorii. Vă este interzis să circulați cu autovehiculul care emană noxe peste limita legal admisă, aceasta faptă constituie contravenție și se sancționează cu amendă prevăzută în clasa a doua de sancțiuni și cu reținerea certificatului de înmatriculare sau de înregistrare. Legislația rutieră nu interzice circulația autoturismelor când nu sunt echipate cu cârlig pentru remorcare, acesta nu este obligatoriu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1102.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1102.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1102; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1101 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-situatii-se-interzice-circulatia-autoturismelor-pe-drumurile-publice","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1101","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1103","batch":"23","category":"Categoria B","question":"Ce tip de coliziuni au cea mai mare forță de distrugere?","answers":["Coliziunile laterale","Coliziunile frontale","Coliziunile din spate"],"correctIndices":[1],"correct":1,"explanation":"Coliziunea frontală este coliziunea cu cea mai mare forță de distrugere. Mai ales când aceasta se produce între două vehicule venind din sensuri opuse. Coliziunea laterală și cea din spate au și ele o forță mare de distrugere, dar cea mai mare forță de distrugere o au coliziunile frontale.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1103.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1103.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1103; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1102 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-tip-de-coliziuni-au-cea-mai-mare-forta-de-distrugere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1102","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1104","batch":"23","category":"Categoria B","question":"Ieșiți cu vehiculul de pe un drum agricol și intenționați să virați la dreapta, intrând în șosea. Din stânga se apropie un alt vehicul. Cine dă prioritate?","answers":["Nu este permisă intrarea pe șosea","Vehiculul care circulă pe șosea, deoarece dvs. circulați din dreapta acestuia","Dvs"],"correctIndices":[2],"correct":2,"explanation":"Drumurile agricole sunt drumuri private, iar conducătorii de vehicule care pătrund pe drumul public venind de pe o proprietate alăturată acestuia trebuie să acorde prioritate celor care circulă pe drumul public. Prin urmare, atunci când ieșiți cu vehiculul de pe un drum agricol și intrați pe un drum public, indiferent în ce direcție intenționați să virați, aveți obligația să acordați prioritate de trecere tuturor vehiculelor care circulă pe drumul public, indiferent de direcția acestora de deplasare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1104.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1104.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1104; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1103 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/iesiti-cu-vehiculul-de-pe-un-drum-agricol-si-intentionati-sa-virati-la-dreapta-intrand-in-sosea-din-stanga-se-apropie-un-alt-vehicul-cine-da","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1103","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1105","batch":"23","category":"Categoria B","question":"Semnalul roșu al semaforului:","answers":["Obligă conducătorii vehiculelor care circulă pe direcția înainte să oprească","Obligă conducătorii vehiculelor, indiferent de direcția de deplasare, să oprească","Permite trecerea autovehiculelor care schimbă direcția de mers spre stânga"],"correctIndices":[1],"correct":1,"explanation":"Semnalul de culoare roșie al semaforului obligă conducătorii de vehicule la oprire, indiferent de direcția acestora de deplasare. De asemenea, acest semnal semnifică oprire și pentru pietoni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1105.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1105.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1105; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1104 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semnalul-rosu-al-semaforului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1104","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1106","batch":"23","category":"Categoria B","question":"Cum veți proceda corect atunci când efectuați un viraj spre stânga sau spre dreapta și intersectați un biciclist care circulă pe o pistă pentru biciclete, semnalizată ca atare?","answers":["Acordați prioritate de trecere biciclistului","Nu acordați prioritate de trecere biciclistului","Adaptați viteza, astfel încât să nu vă intersectați cu acesta în timpul manevrelor"],"correctIndices":[0],"correct":0,"explanation":"Atunci când efectuați viraj către stânga sau către dreapta și vă intersectați cu un conducător de bicicletă sau trotinetă electrică care circulă pe o pistă pentru biciclete, semnalizată ca atare, aveți obligația să acordați prioritate de trecere acestora.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1106.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1106.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1106; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1105 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-corect-atunci-cand-efectuati-un-viraj-spre-stanga-sau-spre-dreapta-si-intersectati-un-biciclist-care-circula-pe-o-pista-pen","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1105","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1107","batch":"23","category":"Categoria B","question":"Ce simptome ale stopului cardiac prezintă o persoană, victimă a unui accident de circulație?","answers":["Leziuni profunde în zona toracelui","Lipsa pulsului","Apariția hemoragiei pe gură"],"correctIndices":[1],"correct":1,"explanation":"Stopul cardiac reprezintă întreruperea bruscă a activității inimii. În cazul victimei rezultate în urma unui accident, stopul cardiac poate fi identificat prin lipsa pulsului. Verificarea activității cardiace se face prin palparea pulsului la artera gâtului sau prin ascultarea bătăilor inimii, punând urechea pe pieptul accidentatului. Alte semne de recunoaștere:","imageUrl":"/nivel-1/quiz-images/rodrive-all/1107.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1107.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1107; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1106 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-simptome-ale-stopului-cardiac-prezinta-o-persoana-victima-a-unui-accident-de-circulatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1106","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1108","batch":"23","category":"Categoria B","question":"Cum procedați în cazul în care aveți o defecţiune la sistemul de rulare pe autostradă?","answers":["Părăsiți carosabilul în timp ce rulează autovehiculul, opriți pe banda de urgență și îl semnalizați","Aprindeți luminile de poziție","Aprindeți proiectoarele"],"correctIndices":[0],"correct":0,"explanation":"Atunci când circulați pe autostradă și apare o defecțiune la sistemul de rulare, trebuie să părăsiți carosabilul în timp ce rulează autovehiculul, opriți pe banda de urgență și îl semnalizați prin punerea în funcțiune a luminilor de avarie și prin instalarea triunghiurilor reflectorizante, în fața și în spatele autovehiculului, la cel puțin 30 de metri. Dacă defecțiunea nu poate fi reparată pe loc, trebuie să apelați la un autovehicul pentru transportul vehiculelor defecte, care să vă scoată în siguranță de pe autostradă și să vă ducă la un service.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1108.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1108.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1108; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1107 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-cazul-in-care-aveti-o-defectiune-la-sistemul-de-rulare-pe-autostrada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1107","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1109","batch":"23","category":"Categoria B","question":"Indicatorul vă avertizează că urmează:","answers":["O urcare cu înclinare mare, pe o lungime de 2000 m","O coborâre periculoasă, cu o diferență de nivel de 10 m până la 100 m pe orizontală","Limitare de viteză la 10 km/h"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul se numește “Urcare periculoasă” și vă avertizează despre existența unui drum în rampă cu înclinare de 10%. Panoul adițional „Lungimea sectorului periculos la care se referă indicatorul” vă informează despre lungimea sectorului periculos la care se referă indicatorul, în cazul de față 2000 metri. Prin urmare, indicatorul împreună cu panoul adițional vă avertizează despre o urcare cu înclinare mare, pe o lungime de 2000 m.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1109.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1109.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1109; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul triunghiular cu margine roșie, o panta neagră și inscripția '10%' avertizează asupra unei pante abrupte de 10%. Panoul adițional de sub el este dreptunghiular și are inscripția 2000m, însoțită de săgeți negre, cu capătul în sus, pe o parte și pe alta a inscripției, ce reprezintă începutul zonei cu panta abruptă, care se întinde pe o distanță de 2000 m.","needsImageReview":true,"source":"RoDrive · ID 1108 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-va-avertizeaza-ca-urmeaza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1108","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1140.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1110","batch":"23","category":"Categoria B","question":"Este permisă deschiderea portierelor autoturismului pe timpul opririi sau staționării pe un drum public?","answers":["Da, numai după ce conducătorul sau pasagerul s-a asigurat că aceasta nu prezintă pericol pentru trafic","Da, numai pe drumurile cu trafic redus","Da, dar numai pe partea dreaptă"],"correctIndices":[0],"correct":0,"explanation":"Pe timpul opririi sau staționării pe un drum public, este permisă deschiderea portierelor autoturismului numai după ce conducătorul sau pasagerul s-a asigurat că aceasta manevră nu prezintă pericol pentru ceilalți participanți la trafic. Intensitatea traficului nu interzice sau permite deschiderea portierelor autoturismului pe timpul opririi sau staționării pe un drum public. Nu este specificat în legislația rutieră pe ce parte a autovehiculului se pot deschide portierele pe timpul opririi sau staționării pe un drum public. Prin urmare, deschiderea acestora este permisă pe ambele părți, dar cu respectarea prevederilor de la varianta A de răspuns.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1110.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1110.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1110; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1109 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-deschiderea-portierelor-autoturismului-pe-timpul-opririi-sau-stationarii-pe-un-drum-public","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1109","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1111","batch":"23","category":"Categoria B","question":"Ce obligații aveți dacă vă aflați la volanul autoturismului albastru?","answers":["Vă continuați deplasarea pe direcția înainte, fără nicio obligație","Acordați prioritate autoturismului roșu și autoturismului verde","Acordați prioritate numai autoturismului verde"],"correctIndices":[1],"correct":1,"explanation":"În această intersecție dirijată prin indicatoare de reglementare de prioritate, dacă vă aflați la volanul autoturismului albastru, trebuie să acordați prioritate de trecere autoturismului roșu, deoarece acesta circulă pe drumul cu prioritate. Dar trebuie să îi acordați prioritate de trecere și autoturismului verde, deoarece între dumneavoastră și acesta s-a creat o situație de egalitate, situație în care se va aplica regula priorității de dreapta, iar autoturismul circulă din partea dreaptă a dumneavoastră. Prin urmare, în această situație, trebuie să le acordați prioritate de trecere ambelor autoturisme.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1111.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1111.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1111; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Această intersecție este reglementată prin indicatoare 'Cedează trecerea' și 'Drum prioritar'. Vehiculul roșu(vine din stânga), aflat pe drumul cu prioritate, vrea să vireze la dreapta, în direcția drumului prioritar. Vehiculul verde, care vine din stânga, vrea să vireze la stânga și are indicatorul triunghiular de cedare a trecerii. Autoturismul albastru vine de sus, vrea să meargă înainte și are și el indicator de cedare a trecerii.","needsImageReview":true,"source":"RoDrive · ID 1110 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-daca-va-aflati-la-volanul-autoturismului-albastru","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1110","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1141.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1112","batch":"23","category":"Categoria B","question":"Este recomandabil să păstrăm sau să depozităm anumite obiecte pe podeaua autovehiculului / tractorului agricol sau forestier?","answers":["Da, atâta vreme cât acestea nu ne stânjenesc în acționarea comenzilor autovehiculului","Da, dacă nu mai există un alt loc în care să așezăm obiectele de mici dimensiuni","Nu, întrucât există posibilitatea rostogolirii acestor obiecte, care pot ajunge sub pedale și crea situații periculoase"],"correctIndices":[2],"correct":2,"explanation":"Nu este recomandabil să păstrați sau să depozitați anumite obiecte pe podeaua autovehiculului, întrucât există posibilitatea ca acestea să se rostogolească și să ajungă sub pedale, împiedicând manevrarea acestora și creând astfel situații periculoase.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1112.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1112.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1112; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1111 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-recomandabil-sa-pastram-sau-sa-depozitam-anumite-obiecte-pe-podeaua-autovehiculului-tractorului-agricol-sau-forestier","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1111","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1113","batch":"23","category":"Categoria B","question":"Cum se sancționează adoptarea unui comportament agresiv în conducerea vehiculelor pe drumurile publice?","answers":["Doar cu amendă contravențională","Amendă contravențională și puncte de penalizare","Amendă contravențională și suspendarea exercitării dreptului de a conduce pentru o perioadă de 30 de zile"],"correctIndices":[2],"correct":2,"explanation":"Adoptarea unui comportament agresiv în conducerea vehiculelor pe drumurile publice se sancționează cu amenda prevăzută înclasaa II-ade sancțiuniși cu suspendarea dreptului de a conducepentru o perioadă de30 de zile. Însă dacă prin adoptarea unui comportament agresiv în conducerea vehiculelor pe drumurile publices-a produs un accident de circulație din care au rezultat avarierea unui vehicul sau alte pagube materiale(însemnând un accident rutier fără victime), se va sancționa mai „aspru”, cu amenda prevăzută înclasaa III-ade sancțiuniși cu suspendarea dreptului de a conducepentru o perioada de60 de zile.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1113.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1113.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1113; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1112 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-se-sanctioneaza-adoptarea-unui-comportament-agresiv-in-conducerea-vehiculelor-pe-drumurile-publice","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1112","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1114","batch":"23","category":"Categoria B","question":"Până la transportarea victimei la spital, poziția de așteptare poate fi:","answers":["O poziție cât mai comodă","O poziție care să permită o bună respirație","O poziție comodă pentru transport"],"correctIndices":[1],"correct":1,"explanation":"Până la transportarea victimei la spital, poziția de așteptare trebuie să fie o poziție care să permită o bună respirație. În funcție de leziuni și/sau de starea pe care victima o prezintă poziționarea va fi:","imageUrl":"/nivel-1/quiz-images/rodrive-all/1114.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1114.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1114; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1113 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pana-la-transportarea-victimei-la-spital-pozitia-de-asteptare-poate-fi","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1113","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1115","batch":"23","category":"Categoria B","question":"Ce obligații vă revin la semnalul agentului de cale ferată de la trecerile la nivel, executat cu un dispozitiv cu lumină roșie ori cu bastonul fluorescent-reflectorizant?","answers":["Să reduceți viteza doar până traversați calea ferată","Să opriți autovehiculul","Să reduceți viteza și să opriți numai dacă circulă un vehicul feroviar"],"correctIndices":[1],"correct":1,"explanation":"Semnalul agenților căilor ferate, aflați la trecerea la nivel cu o cale ferată, executat cu un dispozitiv cu lumină roșie ori cu bastonul fluorescent-reflectorizant, vă obligă să opriți. Agenții de cale ferată se pot întâlni atât la trecerile la nivel cu calea ferată industrială cât industrială cât și la trecere la nivel cu calea ferată curentă.De știut că la trecerea la nivel cu calea ferată industrială, atunci când pe aceasta urmează să se deplaseze un vehicul feroviar, circulația rutieră va fi dirijată obligatoriu de un agent de cale ferată, iar la trecerea la nivel cu calea ferată curentă se poate întâlni un agent de cale ferată care să dirijeze circulația rutieră, dar prezența acestuia nu este obligatorie.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1115.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1115.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1115; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1114 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-va-revin-la-semnalul-agentului-de-cale-ferata-de-la-trecerile-la-nivel-executat-cu-un-dispozitiv-cu-lumina-rosie-ori-cu-bastonu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1114","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1116","batch":"23","category":"Categoria B","question":"Cum veți proceda corect pentru a intra pe autostradă folosind banda de intrare (accelerare):","answers":["Veți respecta semnificația semnalizării rutiere a drumului respectiv","Cedați trecerea autovehiculelor care circulă pe prima bandă a autostrăzii și nu stânjeniți în niciun fel circulația acestora","Nu aveți nicio obligație, deoarece autostrada are suficiente benzi pentru a permite circulația tuturor vehiculelor"],"correctIndices":[0,1],"correct":0,"explanation":"Este bine cunoscut că autovehiculele care se deplasează pe autostradă circulă cu viteză mai mare decât cele de pe celelalte categorii de drumuri, de aceea a fost creată o bandă suplimentară, cu o lungime care să permită autovehiculelor să ajungă la o viteză cel puțin egală cu cea a autovehiculelor din fluxul de trafic al autostrăzii, pentru a se putea integra în trafic în siguranță. Această bandă se numește „Bandă de accelerare” iar regulamentul rutier prevede obligații pentru cei ce folosesc această bandă. Astfel, atunci când doriți să intrați pe autostradă folosind banda de accelerare, trebuie să măriți viteza de deplasare, să cedați trecerea autovehiculelor care circulă pe prima bandă a autostrăzii și să nu stânjeniți în niciun fel circulația acestora. Pe lângă aceste obligații, pe timpul conducerii autovehiculului pe drumurile publice trebuie să respectați și semnificația semnalizării rutiere întâlnită pe respectivul drum, ca de exemplu semnificația indicatoarelor și marcajelor rutiere, semnalele și indicațiile polițistului rutier care dirijează circulația sau semnalizarea temporară","imageUrl":"/nivel-1/quiz-images/rodrive-all/1116.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1116.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1116; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1115 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-corect-pentru-a-intra-pe-autostrada-folosind-banda-de-intrare-accelerare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1115","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1117","batch":"23","category":"Categoria B","question":"Trebuie să acordați prioritate autoturismului negru dacă acesta virează la stânga?","answers":["În funcţie de viteza celor două vehicule","Da","Nu"],"correctIndices":[2],"correct":2,"explanation":"În această situație vă intersectați cu autoturismul negru, indiferent de direcția acestuia de deplasare, trebuie să vă acorde prioritate de trecere deoarece întâlnește indicatorul “Cedează trecerea”. Dumneavoastră, înainte de intersecție ați întâlnit un indicator care vă conferă prioritate de trecere, ca de exemplu indicatorul “Drum cu prioritate” sau indicatorul “Intersecție cu un drum fără prioritate” și aveți prioritate de trecere față de autoturismul negru. Prin urmare, în această situație nu trebuie să acordați prioritate de trecere autoturismului negru.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1117.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1117.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1117; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă perspectiva unui șofer într-o intersecție unde un autoturism negru se află pe un drum secundar semnalizat cu indicatorul triunghiular cu margini roșii, 'Cedează trecerea'. Autoturismul negru vrea să vireze la stânga. Șoferul merge înainte.","needsImageReview":true,"source":"RoDrive · ID 1116 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/trebuie-sa-acordati-prioritate-autoturismului-negru-daca-acesta-vireaza-la-stanga","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1116","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1147.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1118","batch":"23","category":"Categoria B","question":"Cum veți proceda într-o curbă lipsită de vizibilitate, dacă în fața dvs. circulă o bicicletă?","answers":["Reduceți viteza și vă deplasați în spatele bicicletei, până când drumul vă oferă condiții bune de vizibilitate pentru depășire","Claxonați pentru a atrage atenția biciclistului că îl depășiți","Vă continuați deplasarea, deoarece în această situație bicicletele pot fi depășite"],"correctIndices":[0],"correct":0,"explanation":"Depășirea vehiculelor este interzisă în curbe. ATENȚIE!, se interzice depășirea tuturor vehiculelor. Prin urmare, dacă în fața dumneavoastră circulă o bicicletă, trebuie să reduceți viteza și să vă deplasați cu atenție în spatele acesteia până când drumul va oferă condiții bune de vizibilitate pentru a putea efectua manevra de depășire în condiții de siguranță. Atât timp cât depășirea vă este interzisă nu mai are rost să îl atenționați că îl depășiți. În plus, trebuie știut că este interzisă folosirea claxonului de la o distanță mai mică de 25 de metri față de cei cărora li se adresează. Este interzisă depășirea tuturor vehiculelor, inclusiv a bicicletelor. Vezi explicația de la varianta A de răspuns. Pentru a asigura odistanță laterală de siguranță corespunzătoare, conducătorii de autovehicule (cu excepția autovehiculelor cu două roți), vor efectua manevra de depășire a bicicletelor sau a trotinetelor electrice respectând,pe lângă obligațiile privind manevra de depășire,și următoarele obligații,în funcție de viteza cu care aceștia se deplasează(art. 118 alin. 2 din Regulament): În concluzie, dacă te deplasezicu până la 50de km/h ești obligatmăcar să încalci marcajul, iar dacă te deplasezicu mai mult de 50 de km/hești obligatmăcar să treci cu jumătate din lățimea autovehiculului peste marcaj. Trebuie reținut că acestea de mai sus nu sunt doar recomandări, acestea sunt obligații, iar nerespectarea lor se sancționează conform legii. De reținut că în cazul în care un sector de drum are acest marcaj realizat culinie continuănu se mai poate efectua depășirea bicicletelor sau tro","imageUrl":"/nivel-1/quiz-images/rodrive-all/1118.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1118.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1118; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1117 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-intr-o-curba-lipsita-de-vizibilitate-daca-in-fata-dvs-circula-o-bicicleta","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1117","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1119","batch":"23","category":"Categoria B","question":"Cum procedați în situația dată:","answers":["Acordați prioritate de trecere autocamionului","Reduceți viteza și să semnalizați luminos","Vă continuați drumul"],"correctIndices":[2],"correct":2,"explanation":"În situația dată, întâlniți un obstacol imobil pe sensul opus de circulație, vă puteți continua drumul fără a acorda prioritate vehiculelor care circulă din sens opus, deoarece obstacolul se află pe sensul opus de circulație iar drumul pe care circulați nu este în pantă. În situația în care drumul pe care circulați ar fi fost în pantă, aveați obligația să acordați prioritate vehiculelor care urcă dacă pe sensul acestora de deplasare se află un obstacol imobil.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1119.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1119.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1119; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un sector de drum din perspectiva unui șofer cu lucrări semnalizat prin indicatorul triunghiular cu fundal galben și om care lucrează, 'Lucrări pe carosabil'. Pe banda din sens opus circulă un camion, iar autoturismul din față se deplasează pe aceeași bandă. Șoferul se află pe banda fără lucrări.","needsImageReview":true,"source":"RoDrive · ID 1118 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1118","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1149.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1120","batch":"23","category":"Categoria B","question":"Ce semnifică indicatoarele de semnalizare din imagine?","answers":["„ocolire prin stânga“","„panouri succesive pentru curbe deosebit de periculoase, la stânga“","„curbă la stânga“"],"correctIndices":[1],"correct":1,"explanation":"Indicatoarele se numesc “Panouri succesive pentru curbe deosebit de periculoase”, aceste panouri vă avertizează că urmează o curbă deosebit de periculoasă la stânga. În curbele deosebit de periculoase aveți obligația de a circula cu o viteză care să nu depășească 30 km/h în localități și 50km/h în afara localităților. În situatia dată, pentru ca vă aflați în afara localității, aveți obligația de a circula cu maxim 50km/h. Trebuie știut că obligația legală privind viteza de deplasare o aveți doarîn curbele deosebit de periculoase semnalizate ca ataresau în carevizibilitatea este mai mică de 50 de metri. În celelalte tipuri de curbe, adică în cele care nu sunt semnalizate ca fiind curbe deosebit de periculoase sau în cele cu o vizibilitate de peste 50 de metri, nu aveți aceasta obligație legală, dar se recomandă,din punct de vedere al conduitei preventive, să se circule cu viteză redusă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1120.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1120.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1120; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată un drum montan curbat semnalizat cu indicatoare dreptunghiulare, cu săgeți roșii pe fundal alb, spre stânga. Acestea avertizează asupra curbelor periculoase și ghidează șoferul să urmeze traiectoria corectă.","needsImageReview":true,"source":"RoDrive · ID 1119 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnifica-indicatoarele-de-semnalizare-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1119","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1151_(1).jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1121","batch":"23","category":"Categoria B","question":"Cum procedați în această situație, dacă circulația este blocată?","answers":["Nu pătrundeți în intersecție până la deblocarea acesteia","Nu aveți obligația de a ceda trecerea","Veți depăși coloana din față prin stânga"],"correctIndices":[0],"correct":0,"explanation":"În situația dată se observă că intersecția este blocată din cauza aglomerației. Chiar dacă întâlniți indicatorul „Drum cu prioritate”, care vă conferă prioritate de trecere, vă este interzis să pătrundeți în această intersecție, trebuie să opriți și să așteptați deblocarea intersecției. Doar după deblocarea acesteia puteți pătrunde în intersecție. Pentru pătrunderea într-o intersecție atunci când circulația în interiorul acesteia este blocată se aplică amenda contravențională prevăzută în clasa a II-a de sancțiuni și 3 puncte de penalizare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1121.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1121.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1121; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată o intersecție semnalizată cu indicatorul 'Cedează trecerea', blocată. Șoferul intenționează să intre în trecere, posibil având indicator de drum cu prioritare","needsImageReview":true,"source":"RoDrive · ID 1120 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-aceasta-situatie-daca-circulatia-este-blocata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1120","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1153.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1122","batch":"23","category":"Categoria B","question":"Un conducător auto imprudent s-a angajat în depășirea coloanei în care vă aflați, iar din sens opus se apropie la mică distanță un autocamion, care îl semnalizează cu luminile. Cum trebuie să procedați pentru evitarea producerii unui accident?","answers":["Nu aveți nicio obligație și prin urmare vă continuați deplasarea în coloană","Reduceți viteza și măriți astfel distanța față de cel care circulă înaintea dvs., creând condiții celui ce depășește neregulamentar să intre în coloană","Vă apropiați de axul drumului public, pentru a-l determina pe cel angajat în depășirea coloanei să renunțe la această manevră riscantă"],"correctIndices":[1],"correct":1,"explanation":"În cazul în care un conducător auto s-a angajat în depășirea coloanei în care vă aflați, iar din sens opus se apropie la mică distanță un alt vehicul, indiferent dacă acesta îl semnalizează sau nu cu luminile, trebuie să reduceți viteza și măriți astfel distanța față de vehiculul care circula înaintea dumneavoastră, creând condiții celui ce depășește neregulamentar să reintre în coloană, astfel evitați producerea unui accident rutier.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1122.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1122.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1122; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1121 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/un-conducator-auto-imprudent-s-a-angajat-in-depasirea-coloanei-in-care-va-aflati-iar-din-sens-opus-se-apropie-la-mica-distanta-un-autocamion","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1121","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1123","batch":"23","category":"Categoria B","question":"Cum este bine să procedați atunci când, circulând în spatele unui biciclist, constatați că acesta dorește să schimbe direcția de mers?","answers":["Semnalizați sonor intenția de a-l depăși","Îi asigurați condiții pentru realizarea manevrei","Nu aveți nicio obligație, întrucât acesta este un vehicul foarte lent"],"correctIndices":[1],"correct":1,"explanation":"Claxonul poate fi folosit doar de la o distanță de cel puțin 25 de metri de cei cărora li se adresează, iar în cazul de față sunteți prea aproape de acești bicicliști și nu vă este permis să îi claxonați, cu excepția cazului în care se claxonează pentru evitarea unui pericol imediat. Atunci când circulați în spatele unui biciclist și constatați că acesta intenționează să schimbe direcția de mers, trebuie să îi asigurați acestuia condiții pentru finalizarea manevrei. Iar după ce acesta a finalizat manevra, vă puteți angaja în depășire doar dacă sunt condiții optime pentru efectuarea manevrei în condiții de siguranță. Legislația rutieră prevede aceleași reguli de circulație pentru toți conducătorii de vehicule, inclusiv pentru conducătorii de biciclete, prioritatea nefiind stabilită în funcție de tipul sau viteza de deplasare a vehiculului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1123.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1123.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1123; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1122 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-este-bine-sa-procedati-atunci-cand-circuland-in-spatele-unui-biciclist-constatati-ca-acesta-doreste-sa-schimbe-directia-de-mers","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1122","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1124","batch":"23","category":"Categoria B","question":"Cum trebuie să procedați atunci când, circulând pe drumul național într-o localitate rurală, treceți pe lângă o coloană militară care se deplasează în aceeași direcție?","answers":["Măriți viteza și depășiți coloana","Folosiți avertizorul sonor de la minimum 150 m","Reduceți viteza până la limitele prevăzute de lege, dacă drumul are o singură bandă pe sens"],"correctIndices":[2],"correct":2,"explanation":"Conducătorul de vehicul este obligat să circule cu o viteză care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților, la trecerea pe lângă coloane militare, dacă acestea se află în mers sau staționează pe partea carosabilă a drumurilor cu o singură bandă de circulație pe sens. În cazul în care drumul are mai multe benzi de circulație pe sens, această obligație de reducere a vitezei de deplasare nu mai este valabilă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1124.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1124.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1124; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1123 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedati-atunci-cand-circuland-pe-drumul-national-intr-o-localitate-rurala-treceti-pe-langa-o-coloana-militara-care-se-depla","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1123","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1125","batch":"23","category":"Categoria B","question":"Care dintre autovehicule au dreptul să intre în intersecție?","answers":["Autocamionul și motocicleta","Autoturismul și autocamionul","Autoturismul și motocicleta"],"correctIndices":[2],"correct":2,"explanation":"Polițistul rutier execută un semnal cu brațul stâng întins orizontal, acest semnal semnifică oprire pentru toți participanții la trafic a căror direcție inițială de deplasare se intersectează cu brațul acestuia, mai exact pentru cei care circulă din fața polițistului. În această intersecție din fața polițistului circulă autocamionul, acesta fiind obligat să oprească deoarece direcția sa inițială de deplasare se intersectează cu brațul întins al polițistului. Autoturismul și motocicleta își pot continua deplasarea deoarece semnalul polițistului nu li se adresează.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1125.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1125.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1125; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție dirijată de un polițist. Brațul stâng întins lateral indică oprirea vehiculelor care vin din fața polițistului, în timp ce cele din lateral și din spate pot circula. Autoturismul roșu și motocicleta se află pe lateralul polițistului. Camionul se află în fața polițistului.","needsImageReview":true,"source":"RoDrive · ID 1124 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-autovehicule-au-dreptul-sa-intre-in-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1124","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1157.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1126","batch":"23","category":"Categoria B","question":"Cum veți proceda dacă intersecția care urmează este blocată din cauza aglomerației?","answers":["Opriți și așteptați deblocarea intersecției, după care vă continuați deplasarea numai la semnalul verde al semaforului","Vă continuați deplasarea, deoarece semnalul verde vă permite acest lucru","Claxonați și avansați printre celelalte vehicule"],"correctIndices":[0],"correct":0,"explanation":"În situația dată se observă că intersecția este blocată din cauza aglomerației. Chiar dacă semaforul este pe culoarea verde, vă este interzis să pătrundeți în intersecție. Trebuie să opriți și să așteptați deblocarea intersecției. După deblocarea acesteia veți pătrunde în intersecție doar la culoarea verde a semaforului. Pentru pătrunderea într-o intersecție atunci când circulația în interiorul acesteia este blocată, se aplică amendă contravențională și puncte de penalizare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1126.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1126.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1126; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată o trecere de pietoni semnalizată prin semafor verde. Șoferul față de care se face perspectiva vrea și are posibilitatea de a merge înainte, dar intersecția este blocată. În dreapta sa sunt pietoni care nu au voie să traverseze.","needsImageReview":true,"source":"RoDrive · ID 1125 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-daca-intersectia-care-urmeaza-este-blocata-din-cauza-aglomeratiei","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1125","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1158.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1127","batch":"23","category":"Categoria B","question":"Cum procedează conducătorul de vehicul la întâlnirea indicatorului „Oprire“?","answers":["Oprește unde are o bună vizibilitate pentru a se asigura și își continuă deplasarea, dacă pe drumul transversal nu circulă alte vehicule","Reduce viteza, se asigură, după care intră în intersecție","Reduce viteza, după care traversează intersecţia"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul de vehicul care întâlnește indicatorul “Oprire” este obligat să oprească în locul cu vizibilitate maximă, putând trece de indicator, dar fără a depăși colțul intersecției și stând pe loc să acorde prioritate tuturor vehiculelor care circulă pe drumul transversal. Acesta este obligat să oprească și în situația în care nu circulă vehicule pe drumul transversal.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1127.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1127.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1127; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1126 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedeaza-conducatorul-de-vehicul-la-intalnirea-indicatorului-oprire","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1126","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1128","batch":"23","category":"Categoria B","question":"Aveți obligația de a respecta semnificația unui indicator amplasat pe partea stângă a drumului?","answers":["Da, dar numai dacă pe sensul dumneavoastră de mers se execută lucrări","Da, pentru că acționează pe sensul dumneavoastră de mers","Nu, pentru că se adresează circulației din sens invers"],"correctIndices":[1],"correct":1,"explanation":"Conducătorii de vehicule sunt obligați să respecte semnificația tuturor indicatoarelor amplasate cu fața către vehicul, chiar dacă acestea sunt montate pe partea stângă a drumului. În situația dată, veți respecta semnificația panourilor succesive pentru curbele deosebit de periculoase. În curbele deosebit de periculoase aveți obligația de a circula cu o viteză care să nu depășească 30 km/h în localități și 50km/h în afara localităților. În situatia dată, pentru ca vă aflați în afara localității, aveți obligația de a circula cu maxim 50km/h. Trebuie știut că obligația legală privind viteza de deplasare o aveți doarîn curbele deosebit de periculoase semnalizate ca ataresau în carevizibilitatea este mai mică de 50 de metri. În celelalte tipuri de curbe, adică în cele care nu sunt semnalizate ca fiind curbe deosebit de periculoase sau în cele cu o vizibilitate de peste 50 de metri, nu aveți aceasta obligație legală, dar se recomandă,din punct de vedere al conduitei preventive, să se circule cu viteză redusă","imageUrl":"/nivel-1/quiz-images/rodrive-all/1128.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1128.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1128; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum montan acoperit de zăpadă, semnalizat cu indicatoare direcționale (săgeți roșii pe fundal alb). Acestea avertizează asupra curbelor periculoase și ghidează șoferul să urmeze traiectoria corectă.","needsImageReview":true,"source":"RoDrive · ID 1127 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/aveti-obligatia-de-a-respecta-semnificatia-unui-indicator-amplasat-pe-partea-stanga-a-drumului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1127","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1160.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1129","batch":"23","category":"Categoria B","question":"Conducătorul unui vehicul angajat într-un accident din care a rezultat moartea sau rănirea unei persoane poate părăsi locul faptei fără încuviințarea poliției?","answers":["Da, dacă vehiculul a blocat circulația","Da, dacă accidentul nu s-a produs din vina sa","Nu, întrucât fapta constituie infracțiune"],"correctIndices":[2],"correct":2,"explanation":"Dacă ați fost implicat într-un accident de circulație în urmă căruia a rezultat moartea sau vătămarea integrității corporale ori a sănătății unei persoane sunteți obligatsă anunțați imediat polițiala numărul național unic pentru apeluri de urgență 112,să nu modificați sau să ștergeți urmele accidentului,fiindu-vă interzis să părăsiți locul fapteifără încuviințarea poliției sau a procurorului care efectuează cercetarea. Nerespectarea interdicției de a părăsi locul fapteieste considerată infracțiuneși se pedepsește cuînchisoarea de la 2 la 7 ani, caz în care se dispune reținerea permisului de conducere în vederea anulării acestuia și se eliberează o dovadă înlocuitoare fără drept de circulație. Cu toate acestea,NUconstituie infracțiunesituația în care,în lipsa altor mijloace de transport, conducătorul vehiculului implicat în accident transportă el însuși persoana rănită la cel mai apropiat spital,acesta având obligațiade a declara datele personale de identitate și numărul de înmatriculare sau înregistrare a vehiculului condus, date ce se vor consemna într-un registru special, și de a se reîntoarce imediat la locul accidentului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1129.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1129.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1129; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1128 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorul-unui-vehicul-angajat-intr-un-accident-din-care-a-rezultat-moartea-sau-ranirea-unei-persoane-poate-parasi-locul-faptei-fara-incu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1128","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1130","batch":"23","category":"Categoria B","question":"Stopul respirator, în cazul persoanelor accidentate, poate fi determinat de:","answers":["Multiple fracturi ale membrelor","Pierderea intensă de sânge","Astuparea căilor respiratorii"],"correctIndices":[2],"correct":2,"explanation":"Stopul respirator este reprezentat prin oprirea brusca a activității pulmonare, mai este cunoscut sub denumirea de asfixie. Persoanele accidentate pot intra în stop respirator, acesta poate fi cauzat de astuparea căilor respiratorii (nas și gură). Pentru a verifica respirația unei victime se poate folosi o coală de hârtie, care se pune deasupra narilor iar dacă accidentatul respiră aceasta se va mișca, sau o oglindă care se va aburi în cazul în care victima respiră.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1130.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1130.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1130; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1129 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/stopul-respirator-in-cazul-persoanelor-accidentate-poate-fi-determinat-de","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1129","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1131","batch":"23","category":"Categoria B","question":"Poate fi redusă capacitatea de conducere auto după consumul unei cantități relativ mici de alcool?","answers":["Nu, dacă se consumă și o ceașcă de cafea","Chiar și cantitățile mici de alcool pot reduce capacitatea de conducere","Nu, cantitățile mici nu dăunează"],"correctIndices":[1],"correct":1,"explanation":"Consumul de alcool,chiar și în cantități mici, afectează semnificativ gândirea, reflexele și autocontrolul, influențând în mod direct capacitatea de a lua decizii corecte în trafic. Sub influența alcoolului, conducătorii auto pot subestima pericolele, pot ignora regulile de circulație și pot asuma manevre periculoase, precum depășirile imprudente sau viteza excesivă. De asemenea, alcoolul poate induce o stare de relaxare excesivă sau o falsă încredere în abilitățile proprii, reducând vigilența și timpul de reacție în situații critice. Această combinație între decizii riscante și reacții întârziate sporește considerabil riscul de accidente rutiere, punând în pericol atât siguranța conducătorului, cât și a celorlalți participanți la trafic. Alcoolul este responsabil pentru următoarele efecte: Fazele consumului de alcool:","imageUrl":"/nivel-1/quiz-images/rodrive-all/1131.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1131.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1131; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1130 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/poate-fi-redusa-capacitatea-de-conducere-auto-dupa-consumul-unei-cantitati-relativ-mici-de-alcool","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1130","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1132","batch":"23","category":"Categoria B","question":"Când aveți voie să fiți agresiv în timpul conducerii pe drumurile publice?","answers":["Atunci când cel din faţă rulează cu viteză redusă, fără motiv întemeiat","În nicio situaţie, indiferent de ceea ce se întâmplă cu ceilalţi participanţi la trafic","Atunci când cel din faţă v-a făcut semne obscene"],"correctIndices":[1],"correct":1,"explanation":"Conducătorii de vehicule trebuie să aibă un comportament care să nu afecteze fluența și siguranța circulației, să nu pună în pericol viața sau integritatea corporala a persoanelor și să nu aducă prejudicii proprietății publice ori private. Acestora li se interzice și să săvârșească acte sau gesturi obscene, să profereze injurii, să adreseze expresii jignitoare ori vulgare celorlalți participanți la trafic. Prin urmare, conducerea agresivă pe drumurile publice nu este permisă, indiferent de atitudinea sau comportamentul celorlalți participanți la trafic. Nu se ripostează la unele acțiuni agresive ale unor participanți la trafic (nerespectarea regulilor de prioritate, pătrunderea pe semnalul de culoare roșie al semaforului electric, neocolirea centrului imaginar al intersecției etc.) și nu se rulează agresiv dacă ceilalți participanți la trafic rulează cu o viteză redusă fără motiv.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1132.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1132.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1132; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1131 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cand-aveti-voie-sa-fiti-agresiv-in-timpul-conducerii-pe-drumurile-publice","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1131","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1133","batch":"23","category":"Categoria B","question":"Indicatorul pe care îl întâlniți vă informează că urmează:","answers":["O ieșire de pe autostradă","O stație de taxare pentru circulația pe autostrăzi","Un loc special amenajat, unde puteți face o pauză pentru odihnă"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul se întâlnește pe autostrăzi și vă informează că urmează un spațiu de servicii, în cazul de față se referă la un loc special amenajat/parcare, unde puteți face o pauză pentru odihnă. Pe acest indicator se specifică și distanța până la locul la care face referire indicatorul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1133.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1133.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1133; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un sector de autostradă semnalizat cu indicatorul dreptunghiular verde pe care scrie 'Spațiu servicii' situat la 1000 m, ce conține o parcare.","needsImageReview":true,"source":"RoDrive · ID 1132 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-pe-care-il-intalniti-va-informeaza-ca-urmeaza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1132","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1166.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1134","batch":"23","category":"Categoria B","question":"Cum este definită depășirea?","answers":["Trecerea unui vehicul pe lângă altul, când circulă în același sens, dar pe o bandă alăturată","Manevra prin care un vehicul trece înaintea altui vehicul ori pe lângă un obstacol, aflat pe același sens de circulație, prin schimbarea direcției de mers și ieșirea de pe banda de circulație sau din șirul de vehicule în care s-a aflat inițial","Trecerea unui vehicul prin dreptul altuia"],"correctIndices":[1],"correct":1,"explanation":"Depășirea este manevra prin care un vehicul trece înaintea altui vehicul ori pe lângă un obstacol, aflat pe același sens de circulație, prin schimbarea direcției de mers și ieșirea de pe banda de circulație sau din șirul de vehicule în care s-a aflat inițial.[OUG* Art. 45 alin. (1)] DE REȚINUT:","imageUrl":"/nivel-1/quiz-images/rodrive-all/1134.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1134.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1134; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1133 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-este-definita-depasirea","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1133","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1135","batch":"23","category":"Categoria B","question":"Copiii cu înălțimea de până la 135 cm pot fi transportați:","answers":["Pe scaunul din față al autovehiculului, dacă sunt ținuți în brațe de persoane majore","Pe scaunul din față al autovehiculului, având fixată centura de siguranță","În autovehicule, doar dacă sunt fixați sau prinși cu ajutorul unui dispozitiv de fixare în scaun pentru copii"],"correctIndices":[2],"correct":2,"explanation":"Copiii cu înălțimeade până la 135 cmpot fi transportați în autovehicule,dacă sunt fixați sau prinșicu ajutorul unui dispozitiv de fixare în scaun pentru copii instalat în autovehicul. Aceste condiții nu se aplică în cazul transportului în autovehicule destinate transportului public de persoane, precum și în taxi, dacă în acesta din urmăcopilul ocupă orice alt loc decât cel de pe scaunul din față. Transportul copilului în vârstă de până la 3 ani, în acest caz, se realizează sub supravegherea unei persoane, alta decât conducătorul de autovehicul. În cazul transportului de copii în autovehicule, legislația rutieră este foarte strictă, pentru aceștia sunt obligații speciale ce trebuie bine înțelese.Accesați cursul de legislație VIDEO din pasul 1 unde găsiți lecție VIDEO cuobligații la transportul copiilor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1135.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1135.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1135; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1134 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/copiii-cu-inaltimea-de-pana-la-135-cm-pot-fi-transportati","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1134","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1136","batch":"23","category":"Categoria B","question":"În cazul imobilizării unei fracturi, atela trebuie să fie:","answers":["Rigidă și suficient de lungă pentru a cuprinde capetele fracturii","Moale","Nu contează"],"correctIndices":[0],"correct":0,"explanation":"În cazul imobilizării unei fracturi, atela trebuie să fie rigidă și suficient de lungă pentru a cuprinde capetele fracturii. Imobilizarea fracturii la mâini și picioare se face prin fixarea cu atele a două articulații învecinate fracturii, mai sus și mai jos de locul fracturii. Sub atelă se aplică bandaj moale de tifon sau vată pentru prevenirea lezării țesuturilor moi.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1136.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1136.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1136; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1135 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-cazul-imobilizarii-unei-fracturi-atela-trebuie-sa-fie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1135","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1137","batch":"23","category":"Categoria B","question":"Puteți efectua depășirea în situația dată?","answers":["Nu","Da, dacă v-ați asigurat din ambele sensuri că nu se apropie niciun tren","Da, deoarece căruța se deplasează cu o viteză foarte mică"],"correctIndices":[0],"correct":0,"explanation":"În situația dată vă aflați la mai puțin de 50 de metri de o cale ferata curentă, iar depășirea vehiculelor este interzisă pe trecerile la nivel cu calea ferată curentă și la mai puțin de 50 de metri înainte de acestea. Prin urmare, în această situație nu vă este permisă depășirea căruței. Trebuie să așteptați până treceți de calea ferată și să efectuați depășirea acesteia doar atunci când manevra se poate efectua regulamentar și în condiții de siguranță.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1137.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1137.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1137; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere la nivel cu calea ferată semnalizată prin 'Crucea Sfântului Andrei' și bariere ridicate. În fața vehiculului se află o căruță care se deplasează lent. Șoferul și căruța se află în dreptul trecerii, iar marcajul longitudinal este continuu.","needsImageReview":true,"source":"RoDrive · ID 1136 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/puteti-efectua-depasirea-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1136","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1169.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1138","batch":"23","category":"Categoria B","question":"Ce semnificație are indicatorul alăturat?","answers":["Accident","Împroșcare cu criblură","Drum aglomerat"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul se numește “Accident”, acesta se instalează înaintea locului unde s-a produs un accident de circulație ce este în curs de investigare. La întâlnirea acestui indicator aveți obligația să circulați cu o viteză care să nu depășească 30 de km/h în localități și 50 de km/h în afara localităților.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1138.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1138.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1138; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul triunghiular cu margine roșie și simbolul unui accident între două vehicule.","needsImageReview":true,"source":"RoDrive · ID 1137 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnificatie-are-indicatorul-alaturat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1137","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1170.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1139","batch":"23","category":"Categoria B","question":"Sunteți obligat să semnalizați orice schimbare a direcției de mers?","answers":["Numai dacă sunt vehicule care vă urmează","Numai în localități","Da"],"correctIndices":[2],"correct":2,"explanation":"Conducătorul de vehiculul este obligat să semnalizeze din timp intenția de a schimba direcția de mers, cu cel puțin 50 m în localități și 100 m în afara localităților înainte de începerea efectuării manevrei și să mențină în funcțiune semnalizarea schimbării direcției de mers pe întreaga durată a executării manevrei.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1139.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1139.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1139; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1138 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/sunteti-obligat-sa-semnalizati-orice-schimbare-a-directiei-de-mers","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1138","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1140","batch":"23","category":"Categoria B","question":"Puteți efectua depășirea în situația dată?","answers":["Da, deoarece căruța se deplasează foarte încet","Nu, întrucât depășirea este interzisă în această situație","Da, dacă funcționează lumina intermitentă de culoare albă"],"correctIndices":[1],"correct":1,"explanation":"În situația dată vă aflați la mai puțin de 50 de metri de o cale ferata curentă, iar depășirea vehiculelor este interzisă pe trecerile la nivel cu calea ferată curentă și la mai puțin de 50 de metri înainte de acestea. Prin urmare, în această situație nu vă este permisă depășirea căruței. Trebuie să așteptați până treceți de calea ferată și să efectuați depășirea acesteia doar atunci când manevra se poate efectua regulamentar și în condiții de siguranță.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1140.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1140.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1140; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere la nivel cu calea ferată semnalizată prin 'Crucea Sfântului Andrei' și bariere ridicate. În fața vehiculului se află o căruță care se deplasează lent. Șoferul și căruța se află în dreptul trecerii, iar marcajul longitudinal este continuu.","needsImageReview":true,"source":"RoDrive · ID 1139 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/puteti-efectua-depasirea-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1139","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1173.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1141","batch":"23","category":"Categoria B","question":"Este obligatorie dotarea autovehiculelor cu trusă medicală de prim ajutor?","answers":["Da, numai la autovehiculele cu o greutate mai mare de 3,5 t","Nu, fiind doar o recomandare legală","Da, pentru toate autovehiculele care circulă pe drumurile publice"],"correctIndices":[2],"correct":2,"explanation":"Conducătorul de autovehicul, tractor agricol sau forestier și tramvai, indiferent de masa totală maximă autorizată (MTMA), este obligat să poarte în acesta, când este condus pe drumurile publice, trusă medicală de prim ajutor, două triunghiuri reflectorizante și un stingător de incendiu, toate acestea să fie omologate. De la această obligație sunt exceptate autovehiculele din categoriile AM, A1, A2 și A.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1141.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1141.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1141; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1140 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-obligatorie-dotarea-autovehiculelor-cu-trusa-medicala-de-prim-ajutor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1140","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1142","batch":"23","category":"Categoria B","question":"Care dintre cele trei autovehicule va trece ultimul prin intersecția din imagine?","answers":["Motocicleta","Autoturismul roșu","Autoturismul verde"],"correctIndices":[1],"correct":1,"explanation":"Intersecția din imagine estenedirijată, în această situație se va aplica regula priorității de dreapta. Autoturismul roșu îi va acorda prioritate motocicletei deoarece aceasta îi vine din partea dreaptă. Motocicleta îi va acorda prioritate de trecere autoturismului verde deoarece acesta îi vine din partea dreaptă. Autoturismul verde nu trebuie să acorde prioritate de trecere, deci va trece primul prin intersecție. Ordinea de trecere este următoarea: autoturismul verde, urmat de motocicleta, iar ultimul prin această intersecție va trece autoturismul roșu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1142.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1142.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1142; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție nedirijată. Motocicleta vine de sus și vrea să vireze la stânga. Vehiculul verde vine din stânga și circulă înainte. Autoturismul roșu vine din dreapta și circulă înainte.","needsImageReview":true,"source":"RoDrive · ID 1141 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-cele-trei-autovehicule-va-trece-ultimul-prin-intersectia-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1141","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_444.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1143","batch":"23","category":"Categoria B","question":"Purtarea centurii de siguranță este obligatorie în timpul circulației pe drumurile din afara localităților?","answers":["Da","Nu","Legea nu prevede"],"correctIndices":[0],"correct":0,"explanation":"Conducătorii de autovehicule și tractoare agricole sau forestiere și persoanele care ocupă locuri prevăzute prin construcție cu centuri sau dispozitive de siguranță omologatetrebuie să le poarte în timpul circulației pe drumurile publice, indiferent dacă ocupă locurile din față sau din spate ale autovehiculului și indiferent dacă circulă în localitate sau în afara localității. Conducătorii de autovehicule având locuri prevăzute prin construcție cu centuri de siguranță trebuie să informeze pasagerii cu privire la obligația legală de a le purta în timpul circulației pe drumurile publice.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1143.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1143.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1143; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1142 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/purtarea-centurii-de-siguranta-este-obligatorie-in-timpul-circulatiei-pe-drumurile-din-afara-localitatilor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1142","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1144","batch":"23","category":"Categoria B","question":"Autoturismul roșu poate depăși în situația dată?","answers":["Da, deoarece a semnalizat intenția și din sens opus nu se apropie niciun vehicul","Da, deoarece se află la mai mult de 150 m de calea ferată","Nu, deoarece depășește o coloană oprită la trecerea la nivel cu calea ferată"],"correctIndices":[2],"correct":2,"explanation":"La trecerea la nivel cu calea ferată curentă prevăzută cu bariere sau semibariere, vehiculele trebuie să oprească, în ordinea sosirii, înaintea barierelor sau semibarierelor, când acestea sunt închise, în curs de coborâre sau ridicare. Conducătorul autoturismului roșu procedează neregulamentar deoarece nu respectă obligația de a opriîn ordinea sosiriiși se angajează în depășirea coloanei de vehicule oprită la trecerea la nivel cu calea ferată, manevra fiind interzisă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1144.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1144.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1144; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere la nivel cu calea ferată unde bariera este coborâtă. Autoturismul roșu intenționează să depășească o coloană de vehicule care așteaptă în fața barierei, unul după altul.","needsImageReview":true,"source":"RoDrive · ID 1143 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/autoturismul-rosu-poate-depasi-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1143","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1178.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1145","batch":"23","category":"Categoria B","question":"Indicatorul semnifică:","answers":["„aeroport“","„drum aglomerat“","„vânt lateral“"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul de avertizare din imagine semnifică \"Vânt lateral\". Acest indicator este amplasat în locurile unde există frecvent curenți puternici de aer care pot afecta circulația rutieră. Conducătorii auto trebuie să fie atenți la trecerea pe lângă un autovehicul cu gabarit mare deoarece se poate forma fenomenul de absorbție.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1145.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1145.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1145; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul triunghiular cu margine roșie și simbolul vântului lateral, aflat pe autostradă.","needsImageReview":true,"source":"RoDrive · ID 1144 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1144","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1179.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1146","batch":"23","category":"Categoria B","question":"Ce semnificație are indicatorul?","answers":["„drum lunecos“","„drum în lucru“","„drum cu denivelări“"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul din imagine se numește “Drum cu denivelări”. Acest indicator vă avertizează că urmează o porțiune de drum cu denivelări pe partea carosabilă, caz în care aveți obligația de a circula cu o viteză care să nu depășească 30 de km/h în localități și 50 de km/h în afara localităților.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1146.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1146.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1146; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul triunghiular cu margine roșie și simbolul unui drum cu denivelări, aflat pe un drum.","needsImageReview":true,"source":"RoDrive · ID 1145 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnificatie-are-indicatorul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1145","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1180.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1147","batch":"23","category":"Categoria B","question":"Care sunt vitezele maxime admise pentru categoria de autovehicule B1?","answers":["90 km/h pe autostrăzi, 85 km/h pe drumurile expres, 80 km/h pe drumurile naționale europene și 70 km/h pe celelalte categorii de drumuri","100 km/h pe autostrăzi, 90 km/h pe drumurile expres, 80 km/h pe drumurile naționale europene și 70 km/h pe celelalte categorii de drumuri","110 km/h pe autostrăzi, 90 km/h pe drumurile expres, 70 km/h pe drumurile naționale europene și 60 km/h pe celelalte categorii de drumuri"],"correctIndices":[0],"correct":0,"explanation":"(Atenție! Este vorba despre Categoria B1, care nu este aceeași cu categoria B) În localități, viteza maximă admisă pentru toate autovehiculele, indiferent de categoria din care fac parte acestea,este de 50 km/h. În afara localităților, viteza maximă admisă pentru autovehiculele din categoriaB1este de:","imageUrl":"/nivel-1/quiz-images/rodrive-all/1147.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1147.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1147; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1146 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-sunt-vitezele-maxime-admise-pentru-categoria-de-autovehicule-b1","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1146","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1148","batch":"23","category":"Categoria B","question":"Ce trebuie să facă un conducător de vehicul pentru ca depășirea să fie considerată regulamentară?","answers":["Să se asigure că manevra poate fi executată în condiții de siguranță, după care să semnalizeze intenția de schimbare a poziției de mers și să efectueze depășirea","Să semnalizeze din timp intenția de schimbare a direcției de mers","Să mărească viteza de deplasare, astfel încât să scurteze timpul de realizare a depășirii"],"correctIndices":[0],"correct":0,"explanation":"Conducătorul vehiculului care efectuează depășirea are următoarele obligații: Semnalizarea se face abia după ce s-a asigurat că manevra poate fi executată în condiții de siguranță. Legislația rutieră nu obligă ca la efectuarea manevrei de depășire să se mărească viteza de deplasare, astfel încât să se scurteze timpul de realizare a depășirii. Important este ca manevra de depășire să se efectueze în condiții de siguranță și să se respecte obligațiile enumerate la varianta A de răspuns. Trebuie știut că nu este permisă depășirea vitezei maxime admise în timpul depășirii. Amintim faptul că tot manevră de depășire se numește și „ocolirea” unui obstacol de pe partea carosabilă, cum ar fi un vehicul oprit, caz în care depășirea se poate efectua și fără să fie necesar să se mărească viteza de deplasare. Pentru a asigura odistanță laterală de siguranță corespunzătoare, conducătorii de autovehicule (cu excepția autovehiculelor cu două roți), vor efectua manevra de depășire a bicicletelor sau a trotinetelor electrice respectând,pe lângă obligațiile privind manevra de depășire,și următoarele obligații,în funcție de viteza cu care aceștia se deplasează(art. 118 alin. 2 din Regulament): În concluzie, dacă te deplasezicu până la 50de km/h ești obligatmăcar să încalci marcajul, iar dacă te deplasezicu mai mult de 50 de km/hești obligatmăcar să treci cu jumătate din lățimea autovehiculului peste marcaj. Trebuie reținut că acestea de mai sus nu sunt doar recomandări, acestea sunt obligații, iar nerespectarea lor se sancționează conform legii. De reținut că în cazul în care un sector de drum","imageUrl":"/nivel-1/quiz-images/rodrive-all/1148.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1148.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1148; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1147 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-faca-un-conducator-de-vehicul-pentru-ca-depasirea-sa-fie-considerata-regulamentara","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1147","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1149","batch":"23","category":"Categoria B","question":"Unde trebuie să așteptați dacă vă aflați la o trecere de cale ferată cu bariera coborâtă?","answers":["La panoul cu două dungi","În fața indicatorului în cruce","În fața barierei"],"correctIndices":[2],"correct":2,"explanation":"La trecerea la nivel cu calea ferată curentă, atunci când barierele sunt coborâte, în curs de coborâre sau de ridicare, aveți obligația de a opri în fața barierei. Vehiculele trebuie să oprească, în ordinea sosirii, înaintea barierelor sau semibarierelor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1149.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1149.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1149; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1148 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/unde-trebuie-sa-asteptati-daca-va-aflati-la-o-trecere-de-cale-ferata-cu-bariera-coborata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1148","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1150","batch":"23","category":"Categoria B","question":"Certificatul de înmatriculare se reține atunci când:","answers":["Vehiculul nu are efectuată inspecția tehnică","Sunt aplicate abțibilduri pe parbriz","Există defecțiuni la sistemul de climatizare"],"correctIndices":[0],"correct":0,"explanation":"Certificatul de înmatriculare sau de înregistrare ori dovada înlocuitoare a acestuia se reține de către poliția rutieră atunci când: Nu se aplică reținerea certificatului de înmatriculare dacă sunt aplicate abţibilduri pe parbriz, atât timp cât acestea nu restrâng sau estompează vizibilitatea în timpul mersului, atât din interior, cât și din exterior. Conducătorul de autovehicul, tractor agricol sau forestier ori tramvai este obligat să verifice funcționarea instalației de climatizare. Nerespectarea acestei obligații, circulând cu instalația de climatizare defectă, constituie contravenție și se sancționează cu amenda prevăzută în clasa I de sancțiuni. Pentru această contravenție nu se aplică reținerea certificatului de înmatriculare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1150.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1150.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1150; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1149 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/certificatul-de-inmatriculare-se-retine-atunci-cand","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1149","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
